@startuml
class Center {
  +name : string
  +address : string
}

class Room {
  +number : int
  +maxCapacity : int
}

class Person {
  +firstName : string
  +familyName : string
  +birthDate : date
}

class Trainer extends Person {
  +diploma : string
}

class Member extends Person {}

class Session {
  +date : date
  +startingHour : time
}

class GroupSession extends Session {
  +type : string
}

class IndividualSession extends Session {}

Center "1" *-- "1..*" Room
Center "1" -- "*" Session
Room "1" -- "*" Session
Trainer "0..1" -- "*" GroupSession : supervises
Member "0..*" -- "*" Session : participates in
@enduml

